struct Rva008A1050Entry { const char* m_name; int m_index; };

struct Rva008A1050Table
{
	unsigned char m_pad0[0x18];
	int* m_values;
	unsigned char m_pad1[0x30 - 0x1c];
	int m_count;
	Rva008A1050Entry* m_entries;
};

struct Rva008A1050Owner
{
	unsigned char m_pad0[0x10];
	Rva008A1050Table* m_table;

	int findNamedSlot(const char* name);
};

int Rva008A1050Owner::findNamedSlot(const char* name)
{
	Rva008A1050Table* t = m_table;
	int count = t->m_count;
	if (count <= 0)
		return 0;

	Rva008A1050Entry* e = t->m_entries;
	for (int i = 0; i < count; ++i, ++e) {
		const char* a = name;
		const char* b = e->m_name;
		bool match = true;
		for (;;) {
			char ca = *a;
			char cb = *b;
			if (ca != cb) { match = false; break; }
			if (ca == 0) break;
			++a; ++b;
		}
		if (match)
			return t->m_values[e->m_index];
	}
	return 0;
}
